import { cva, type VariantProps } from 'class-variance-authority';
import * as React from 'react';

import { cn } from '@utils/cn';

const badgeVariants = cva(
  'inline-flex items-center rounded-md border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2',
  {
    variants: {
      variant: {
        default: 'border-transparent bg-primary text-primary-foreground shadow hover:bg-primary/80',
        success: 'border-transparent bg-green-600 text-white shadow hover:bg-green-700',
        warning: 'border-transparent bg-yellow-600 text-white shadow hover:bg-yellow-700',
        error: 'border-transparent bg-red-600 text-white shadow hover:bg-red-700',
        quantum:
          'border-terra-cyan bg-gradient-to-r from-terra-cyan/20 to-terra-blue/20 text-terra-cyan shadow-lg hover:shadow-[0_0_10px_rgba(0,255,255,0.4)]',
        secondary:
          'border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80',
        destructive:
          'border-transparent bg-destructive text-destructive-foreground shadow hover:bg-destructive/80',
        outline: 'text-foreground',
      },
    },
    defaultVariants: {
      variant: 'default',
    },
  }
);

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof badgeVariants> {
  pulse?: boolean;
}

function Badge({ className, variant, pulse = false, ...props }: BadgeProps) {
  const pulseClasses = pulse ? 'animate-pulse' : '';

  return <div className={cn(badgeVariants({ variant }), pulseClasses, className)} {...props} />;
}

export { Badge, badgeVariants };
